# frozen_string_literal: true

require "roo"

module Mapviz
  # Wrapper around Array of Hashes generated by reading mappings file
  class Worksheet
    def initialize
      @all = Roo::Excelx.new(Mapviz::Path.mappings_file)
        .sheet(Mapviz::Xlsx.worksheet)
        .parse(headers: true)
        .map { |row| row.transform_keys(&:to_sym) }
    end

    # @return [Array<Symbol>]
    def headers = @headers ||= all.first.keys

    # @return [Array<Hash>]
    def rows = @rows ||= all[1..]

    private

    attr_reader :all
  end
end
